# Faellig? `payment.dueDate` kommt auf der Liste leer zurueck, also aus dem
# Belegdatum und dem Zahlungsziel der Rechnung selbst rechnen. `days_since` ist
# der Datums-Helfer der Laufzeit - ein eigener Import waere nicht erlaubt.
ausgestellt = ((rechnung.get('dates') or {}).get('issued')) or ''
ziel = int((((rechnung.get('payment') or {}).get('terms') or {}).get('dueDays')) or 0)
ueberfaellig = (days_since(ausgestellt) - ziel) if ausgestellt else None

stufen = ['paymentReminder1', 'reminder1', 'reminder2', 'reminder3',
          'debtCollection', 'lossOfReceivables']
aktuell = (rechnung.get('dunning') or {}).get('level')
nummer = rechnung.get('number')

result = None
if bool((rechnung.get('dunning') or {}).get('blocked')):
    log(f"{nummer}: Mahnsperre gesetzt - uebersprungen")
elif ueberfaellig is None or ueberfaellig <= 0:
    log(f"{nummer}: noch nicht faellig")
elif not aktuell:
    result = {'level': stufen[0]}
elif aktuell in stufen and stufen.index(aktuell) + 1 < len(stufen):
    result = {'level': stufen[stufen.index(aktuell) + 1]}
else:
    log(f"{nummer}: hoechste Stufe ({aktuell}) bereits erreicht")
if result:
    log(f"{nummer}: {ueberfaellig} Tage ueberfaellig, {aktuell or 'keine'} -> {result['level']}")
